(function(root){const copy=x=>JSON.parse(JSON.stringify(x));const object=x=>x&&typeof x==='object'&&!Array.isArray(x);function normalize(scene,index){if(!object(scene))throw Error('场景 '+(index+1)+' 需要是对象');const id=scene.scene_id||scene.id;if(typeof id!=='string'||!id.trim())throw Error('每个场景都需要 scene_id');if(typeof scene.name!=='string'||!scene.name.trim())throw Error('每个场景都需要 name');for(const k of ['zones','camera_anchors','connected_to'])if(scene[k]!==undefined&&!Array.isArray(scene[k]))throw Error(id+' 的 '+k+' 需要是数组');return{...copy(scene),id,scene_id:id,name:scene.name.trim(),prompt:scene.prompt||scene.generation?.prompt||scene.generation?.positive_prompt||'',negativePrompt:scene.negativePrompt||scene.generation?.negative_prompt||'',sceneVersions:scene.sceneVersions||[],jobs:scene.jobs||{},activeVersions:scene.activeVersions||{},activeView:scene.activeView||'master'};}function parse(raw,currentProjectId){if(!object(raw))throw Error('场景文件需要是 JSON 对象');if(raw.project_id&&currentProjectId&&raw.project_id!==currentProjectId)throw Error('场景文件的 project_id 与当前项目不同，请先导入对应总纲');const list=raw.scenes||(raw.scene_id?[raw]:null);if(!Array.isArray(list)||!list.length)throw Error('文件中没有 scenes 场景数组');const scenes=list.map(normalize),ids=new Set();for(const s of scenes){if(ids.has(s.id))throw Error('场景 ID 重复：'+s.id);ids.add(s.id);}const library={};for(const k of ['description','world_layout','variant_template','version','coordinate_system','shared_world','scene_states','generation_rules','linked_files'])if(raw[k]!==undefined)library[k]=copy(raw[k]);return{scenes,library,project_id:raw.project_id};}function merge(project,raw){const parsed=parse(raw,project.project_id),next=copy(project);next.scenes??=[];for(const scene of parsed.scenes){const i=next.scenes.findIndex(s=>(s.scene_id||s.id)===scene.id);if(i<0)next.scenes.push(scene);else{const previous=next.scenes[i];next.scenes[i]={...scene,sceneVersions:previous.sceneVersions||[],jobs:previous.jobs||{},activeVersions:previous.activeVersions||{},confirmedMasterJobId:previous.confirmedMasterJobId,activeView:previous.activeView||'master',imageSize:previous.imageSize,referenceSceneId:scene.generation?.mode?undefined:previous.referenceSceneId};}}next.sceneLibrary={...(next.sceneLibrary||{}),...parsed.library};if(parsed.project_id&&!next.project_id)next.project_id=parsed.project_id;return{project:next,count:parsed.scenes.length};}function pack(project){return{project_id:project.project_id||'',schema_type:'scene_library',version:project.sceneLibrary?.version||'3.0',...(project.sceneLibrary||{}),scenes:project.scenes||[]};}const api={normalize,parse,merge,pack};if(typeof module!=='undefined')module.exports=api;else root.SceneSchema=api;})(typeof window==='undefined'?globalThis:window);
